"""Original workspace exercises. Rerunnable; never derives content from a book."""
import json,re
from pathlib import Path
root=Path(__file__).resolve().parent.parent
path=root/'content/quizzes.json'
old=json.loads(path.read_text());old=[q for q in old if not q.get('workspace')]
for i,q in enumerate(old):q.setdefault('legacyIndex',i)
new=[]
def keys(s):return re.findall(r'<[^>]+>|[\s\S]',s)
def add(topic,title,files,start,goal,solution,hint,why,**initial):
 w=dict(files=files,start=start,goal=goal,**initial)
 new.append(dict(topic=topic,title=title,before=files[start],after='Workspace goal: '+title,cursor=[0,0],keys=keys(solution),hint=hint,why=why,workspace=w))
add('Buffers','Open the recipe buffer without changing either file.',{'notes.txt':'Buy moon flour.','recipe.txt':'Mix, bake, share.'},'notes.txt',{'current':'recipe.txt'},':bnext<Enter>','Use :bnext to visit the next loaded buffer.','A buffer holds file contents; one window can display different buffers.')
add('Buffers','Open the previous buffer: the launch checklist.',{'checklist.txt':'snacks\nseatbelts','radio.txt':'Channel 4'},'radio.txt',{'current':'checklist.txt'},':bprevious<Enter>','Use :bprevious (or :bp).','Buffer order is independent of where the files appear in the project.')
add('Buffers','Open config.json by name, leaving the notes alone.',{'notes.md':'Do not change the notes.','config.json':'{"snacks": true}','log.txt':'booted'},'notes.md',{'current':'config.json'},':buffer config.json<Enter>','Use :buffer config.json.','Naming a loaded buffer is more reliable than counting through a long list.')
add('Buffers','Visit the menu, then return to the alternate buffer: orders.txt.',{'orders.txt':'Two teas.','menu.txt':'Tea · Cocoa'},'orders.txt',{'current':'orders.txt','listed':['orders.txt','menu.txt']},':buffer menu.txt<Enter>:buffer #<Enter>','Use :buffer menu.txt, then :buffer # to return.','The alternate buffer is the file you most recently left.')
# Require a genuine visit rather than an already-satisfied navigation task.
new[-1]['workspace']['goal']['alternate']='menu.txt'
add('Buffers','Fix “teh” in draft.txt, save it, and return to notes.txt.',{'notes.txt':'Review the draft.','draft.txt':'teh moon'},'notes.txt',{'current':'notes.txt','files':{'draft.txt':'the moon'}},':buffer draft.txt<Enter>lxp:write<Enter>:buffer #<Enter>','Open draft.txt, swap the misplaced letters with lxp, :write, then :buffer #.','Saving before leaving a modified buffer avoids losing work and Vim’s unsaved-change warning.')
add('Buffers','Remove scratch.txt from the buffer list; keep both project files loaded.',{'main.js':'launch();','notes.md':'Ship gently.','scratch.txt':'temporary thoughts'},'scratch.txt',{'current':'main.js','listed':['main.js','notes.md']},':bdelete<Enter>','Use :bdelete on the scratch buffer.','Deleting a buffer removes it from the list; it does not delete the file from disk.')
add('Splits','Open guide.txt beside main.js, with the guide active on the left.',{'main.js':'launch();','guide.txt':'Check snacks before launch.'},'main.js',{'current':'guide.txt','panes':['guide.txt','main.js'],'layout':'vertical'},':vsplit guide.txt<Enter>','Use :vsplit guide.txt.','With default Vim split placement, a vertical split opens to the left.')
add('Splits','Open notes.txt above the recipe, keeping both visible.',{'recipe.txt':'mix\nbake','notes.txt':'Use a small tin.'},'recipe.txt',{'current':'notes.txt','panes':['notes.txt','recipe.txt'],'layout':'horizontal'},':split notes.txt<Enter>','Use :split notes.txt.','A horizontal split opens above the current window by default.')
add('Splits','Focus main.js in the right pane without closing the guide.',{'guide.txt':'Launch gently.','main.js':'launch();'},'guide.txt',{'current':'main.js','panes':['guide.txt','main.js'],'layout':'vertical'},'<C-w>l','Press Ctrl+w, then l.','Window navigation combines Ctrl+w with familiar direction keys.',panes=['guide.txt','main.js'],layout='vertical')
add('Splits','Move to the lower pane, fix “teh” to “the”, and save the log.',{'notes.txt':'Keep this note visible.','log.txt':'teh launch succeeded'},'notes.txt',{'current':'log.txt','panes':['notes.txt','log.txt'],'layout':'horizontal','files':{'log.txt':'the launch succeeded'}},'<C-w>jlxp:write<Enter>','Ctrl+w j moves down. Use lxp to fix the typo, then :write.','Moving between windows does not move or merge their text.',panes=['notes.txt','log.txt'],layout='horizontal')
add('Splits','Keep only the guide pane; leave main.js in the buffer list.',{'guide.txt':'Keep the map.','main.js':'navigate();'},'guide.txt',{'current':'guide.txt','panes':['guide.txt'],'layout':'single','listed':['guide.txt','main.js']},'<C-w>o','Use Ctrl+w o (or :only).','Closing windows is different from deleting buffers: their files remain available.',panes=['guide.txt','main.js'],layout='vertical')
add('Splits','Copy “Moon Spoon” into the empty sign and save it, keeping both panes.',{'title.txt':'Moon Spoon','sign.txt':'label=""'},'title.txt',{'current':'sign.txt','panes':['title.txt','sign.txt'],'layout':'vertical','files':{'sign.txt':'label="Moon Spoon"'}},'0y$<C-w>lf"p:write<Enter>','Yank the title with 0y$, move right with Ctrl+w l, then f"p and :write.','Registers let you move text between windows without retyping it.',panes=['title.txt','sign.txt'],layout='vertical')
def entries(*items):return [dict(file=f,line=l,ch=c,text=t) for f,l,c,t in items]
qf=entries(('engine.js',1,0,'typo'),('ui.js',0,0,'typo'),('tests.js',1,0,'typo'))
files={'engine.js':'start();\nteh engine','ui.js':'teh screen','tests.js':'test();\nteh assertion'}
add('Quickfix','Show the supplied three-item diagnostic list.',files,'engine.js',{'quickfixOpen':True},':copen<Enter>','Use :copen to show the supplied quickfix list.','Quickfix stores locations from diagnostics or search results; opening it does not change files.',quickfix=qf)
add('Quickfix','Jump to the second diagnostic in ui.js.',files,'engine.js',{'current':'ui.js','cursor':[0,0]},':cnext<Enter>','The first entry is selected. :cnext jumps to the next diagnostic.','Quickfix navigation follows the result list, not buffer order.',quickfix=qf)
add('Quickfix','Jump directly to the last diagnostic in tests.js.',files,'engine.js',{'current':'tests.js','cursor':[1,0]},':clast<Enter>','Use :clast.','The last quickfix entry can point to a different file and line.',quickfix=qf)
add('Quickfix','Jump to diagnostic 2, fix its typo, and save ui.js.',files,'engine.js',{'current':'ui.js','files':{'ui.js':'the screen'}},':cc 2<Enter>lxp:write<Enter>','Use :cc 2, then lxp and :write.','A numbered quickfix jump goes straight to one problem without touching the others.',quickfix=qf)
add('Quickfix','Fix and save the first two diagnostics, then return to the first.',files,'engine.js',{'current':'engine.js','cursor':[1,0],'files':{'engine.js':'start();\nthe engine','ui.js':'the screen'}},':cfirst<Enter>lxp:write<Enter>:cnext<Enter>lxp:write<Enter>:cprevious<Enter>','Use :cfirst, fix and save; :cnext, fix and save; :cprevious returns.','Save between diagnostic jumps; the list remains useful while you repair multiple files.',quickfix=qf)
add('Quickfix','Open the diagnostics, visit the final entry, then hide the list.',files,'engine.js',{'current':'tests.js','cursor':[1,0],'quickfixOpen':False},':copen<Enter>:clast<Enter>:cclose<Enter>','Use :copen, :clast, then :cclose.','Closing the quickfix window keeps both the results and your current file.',quickfix=qf)
add('Project search','Find TODO in every JavaScript file and show the result list.',{'a.js':'// TODO snacks\nrun();','b.js':'// TODO tickets','notes.md':'TODO private note'},'notes.md',{'current':'a.js','quickfixOpen':True,'matches':entries(('a.js',0,3,''),('b.js',0,3,''))},':vimgrep /TODO/ *.js<Enter>:copen<Enter>','Use :vimgrep /TODO/ *.js, then :copen.','A project search fills quickfix with matching locations, limited by the filename pattern.')
add('Project search','Find launch() in nested src files, excluding the test fixture.',{'notes.txt':'Find the launch sites.','src/a.js':'launch();','src/lib/b.js':'prepare();\nlaunch();','tests/a.js':'launch();'},'notes.txt',{'current':'src/a.js','matches':entries(('src/a.js',0,0,''),('src/lib/b.js',1,0,''))},':vimgrep /launch/ src/**/*.js<Enter>','Use :vimgrep /launch/ src/**/*.js.','The recursive ** glob includes nested directories while keeping the search inside src.')
add('Project search','Collect TODO matches without leaving notes.txt, and show the results.',{'notes.txt':'Stay here while searching.','a.js':'// TODO tea','b.js':'// TODO toast'},'notes.txt',{'current':'notes.txt','quickfixOpen':True,'matches':entries(('a.js',0,3,''),('b.js',0,3,''))},':vimgrep /TODO/j *.js<Enter>:copen<Enter>','The j flag collects results without jumping: :vimgrep /TODO/j *.js.','Use the j flag when gathering locations should not interrupt the current file.')
add('Project search','Find both “red” occurrences on the same line, then jump to the second.',{'notes.txt':'Find every color.','palette.txt':'red blue red'},'notes.txt',{'current':'palette.txt','cursor':[0,9],'matches':entries(('palette.txt',0,0,''),('palette.txt',0,9,''))},':vimgrep /red/g palette.txt<Enter>:cnext<Enter>','Use the g flag to collect every match on a line, then :cnext.','Without g, vimgrep records only the first match on each matching line.')
add('Project search','Find the two obsolete flags, change both to true, and save each file.',{'notes.md':'Enable the release.','a.cfg':'enabled=false','b.cfg':'enabled=false','keep.txt':'enabled=false'},'notes.md',{'current':'b.cfg','files':{'a.cfg':'enabled=true','b.cfg':'enabled=true'},'matches':entries(('a.cfg',0,8,''),('b.cfg',0,8,''))},':vimgrep /false/ *.cfg<Enter>ciwtrue<Esc>:write<Enter>:cnext<Enter>ciwtrue<Esc>:write<Enter>','Search *.cfg for false, change the matched word, save, and repeat at :cnext.','Search scope protects unrelated files; quickfix supplies the locations for deliberate edits.')
add('Project search','Find TODO only at line starts, preserving the inline note as a non-match.',{'notes.md':'Find unassigned tasks.','tasks.txt':'TODO tea\nkeep TODO inline\nTODO toast'},'notes.md',{'current':'tasks.txt','matches':entries(('tasks.txt',0,0,''),('tasks.txt',2,0,'')),'quickfixOpen':True},':vimgrep /^TODO/ tasks.txt<Enter>:copen<Enter>','Anchor with ^: :vimgrep /^TODO/ tasks.txt, then :copen.','A deliberate pattern reduces noisy results before you start visiting files.')
omissions=root/'content/omitted-native-compatibility.json'
omitted_titles={x['quiz']['title'] for x in json.loads(omissions.read_text())} if omissions.exists() else set()
new=[q for q in new if q['title'] not in omitted_titles]
allq=old+new
# The editorial manifest owns sequencing. Preserve existing quiz metadata and
# reapply it after refreshing the embedded workspace fixtures.
path.write_text(json.dumps(allq,ensure_ascii=False,indent=2)+'\n')
import subprocess,sys
subprocess.run([sys.executable,str(root/'scripts/curate-course.py')],check=True)
print('Refreshed',len(new),'workspace exercises.')
